7	use comemo::{Track, Tracked, TrackedMut};
8	use ecow::EcoVec;
9	use typst_library::diag::SourceResult;
10	use typst_library::engine::{Engine, Route, Sink, Traced};
11	use typst_library::foundations::{Content, StyleChain};
12	use typst_library::introspection::{
13	    Introspector, Locator, LocatorLink, ManualPageCounter, SplitLocator, TagElem,
14	};
15	use typst_library::layout::{FrameItem, Point};
16	use typst_library::model::DocumentInfo;
17	use typst_library::routines::{Arenas, Pair, RealizationKind};
18	use typst_library::{Library, World};
19	use typst_utils::{LazyHash, Protected};
20	
21	use self::collect::{Item, collect};
22	use self::finalize::finalize;
23	use self::run::{LayoutedPage, layout_blank_page, layout_page_run};
24	use crate::{Page, PagedDocument};
25	
26	/// Layout content into a document.
27	///
28	/// This first performs root-level realization and then lays out the resulting
29	/// elements. In contrast to [`layout_fragment`](crate::layout_fragment),
30	/// this does not take regions since the regions are defined by the page
31	/// configuration in the content and style chain.
32	#[typst_macros::time(name = "layout document")]
33	pub fn layout_document(
34	    engine: &mut Engine,
35	    content: &Content,
36	    styles: StyleChain,
37	) -> SourceResult<PagedDocument> {
38	    layout_document_impl(
39	        engine.world,
40	        engine.library,
41	        engine.introspector.into_raw(),
42	        engine.traced,
