124	const LIST_RULE: ShowFn<ListElem> = |elem, _, styles| {
125	    let tight = elem.tight.get(styles);
126	
127	    let mut realized = BlockElem::multi_layouter(elem.clone(), crate::lists::layout_list)
128	        .pack()
129	        .spanned(elem.span());
