49	/// Layout an inline equation (in a paragraph).
50	#[typst_macros::time(span = elem.span())]
51	pub fn layout_equation_inline(
52	    elem: &Packed<EquationElem>,
53	    engine: &mut Engine,
54	    locator: Locator,
55	    styles: StyleChain,
56	    region: Size,
57	) -> SourceResult<Vec<InlineItem>> {
58	    assert!(!elem.block.get(styles));
59	
60	    let span = elem.span();
61	    let font = get_font(engine.world, styles, span)?;
62	    warn_non_math_font(&font, engine, span);
63	
64	    let scale_style = style_for_script_scale(&font);
65	    let styles = styles.chain(&scale_style);
66	
67	    let arenas = Arenas::default();
68	    let item = resolve_equation(elem, engine, locator, &arenas, styles)?;
69	
70	    let mut ctx = MathContext::new(engine, region, font.clone());
71	    let mut items = if !item.is_multiline() {
72	        ctx.layout_into_fragments(&item, styles)?.into_par_items()
73	    } else {
74	        vec![InlineItem::Frame(ctx.layout_into_fragment(&item, styles)?.into_frame())]
75	    };
76	
77	    // An empty equation should have a height, so we still create a frame
78	    // (which is then resized in the loop).
79	    if items.is_empty() {
80	        items.push(InlineItem::Frame(Frame::soft(Size::zero())));
81	    }
82	
83	    for item in &mut items {
84	        let InlineItem::Frame(frame) = item else { continue };
85	
86	        let slack = styles.resolve(ParElem::leading) * 0.7;
87	
88	        let (t, b) = font.edges(
89	            styles.get(TextElem::top_edge),
90	            styles.get(TextElem::bottom_edge),
91	            styles.resolve(TextElem::size),
92	            TextEdgeBounds::Frame(frame),
93	        );
94	
95	        let ascent = t.max(frame.ascent() - slack);
96	        let descent = b.max(frame.descent() - slack);
97	        frame.translate(Point::with_y(ascent - frame.baseline()));
98	        frame.size_mut().y = ascent + descent;
99	    }
100	
101	    Ok(items)
102	}
103	
104	/// Layout a block-level equation (in a flow).
105	#[typst_macros::time(span = elem.span())]
106	pub fn layout_equation_block(
107	    elem: &Packed<EquationElem>,
108	    engine: &mut Engine,
109	    locator: Locator,
110	    styles: StyleChain,
111	    regions: Regions,
112	) -> SourceResult<Fragment> {
113	    assert!(elem.block.get(styles));
114	
115	    let span = elem.span();
116	    let font = get_font(engine.world, styles, span)?;
117	    warn_non_math_font(&font, engine, span);
118	
119	    let scale_style = style_for_script_scale(&font);
120	    let styles = styles.chain(&scale_style);
121	
122	    let arenas = Arenas::default();
123	    let item = resolve_equation(elem, engine, locator.relayout(), &arenas, styles)?;
124	
125	    let mut ctx = MathContext::new(engine, regions.base(), font.clone());
126	    let full_equation_builder = if let MathItem::Component(MathComponent {
127	        kind: MathKind::Multiline(multi),
128	        styles,
129	        ..
130	    }) = item
131	    {
132	        layout_multiline(&multi, &mut ctx, styles)?
133	    } else {
134	        ctx.layout_into_fragments(&item, styles)?.into_frame().into()
135	    };
136	    let width = full_equation_builder.size.x;
137	
138	    let equation_builders = if styles.get(BlockElem::breakable) {
139	        let mut rows = full_equation_builder.frames.into_iter().peekable();
140	        let mut equation_builders = vec![];
141	        let mut last_first_pos = Point::zero();
142	        let mut regions = regions;
143	
144	        // Keep track of the position of the first row in this region,
145	        // so that the offset can be reverted later.
146	        while let Some(&(_, first_pos)) = rows.peek() {
147	            last_first_pos = first_pos;
148	
149	            let mut frames = vec![];
150	            let mut height = Abs::zero();
151	            while let Some((sub, pos)) = rows.peek() {
152	                let mut pos = *pos;
153	                pos.y -= first_pos.y;
154	
155	                // Finish this region if the line doesn't fit. Only do it if
156	                // we placed at least one line _or_ we still have non-last
157	                // regions. Crucially, we don't want to infinitely create
158	                // new regions which are too small.
159	                if !regions.size.y.fits(sub.height() + pos.y)
160	                    && (regions.may_progress()
161	                        || (regions.may_break() && !frames.is_empty()))
162	                {
163	                    break;
164	                }
165	
166	                let (sub, _) = rows.next().unwrap();
167	                height = height.max(pos.y + sub.height());
168	                frames.push((sub, pos));
169	            }
170	
171	            equation_builders
172	                .push(MathRunFrameBuilder { frames, size: Size::new(width, height) });
173	            regions.next();
174	        }
175	
176	        // Append remaining rows to the equation builder of the last region.
177	        if let Some(equation_builder) = equation_builders.last_mut() {
178	            equation_builder.frames.extend(rows.map(|(frame, mut pos)| {
179	                pos.y -= last_first_pos.y;
180	                (frame, pos)
181	            }));
182	
183	            let height = equation_builder
184	                .frames
185	                .iter()
186	                .map(|(frame, pos)| frame.height() + pos.y)
187	                .max()
188	                .unwrap_or(equation_builder.size.y);
189	
190	            equation_builder.size.y = height;
191	        }
192	
193	        // Ensure that there is at least one frame, even for empty equations.
194	        if equation_builders.is_empty() {
195	            equation_builders
196	                .push(MathRunFrameBuilder { frames: vec![], size: Size::zero() });
197	        }
198	
199	        equation_builders
200	    } else {
201	        vec![full_equation_builder]
202	    };
203	
204	    let Some(numbering) = elem.numbering.get_ref(styles) else {
205	        let frames = equation_builders
206	            .into_iter()
207	            .map(MathRunFrameBuilder::build_aligned)
208	            .collect();
209	        return Ok(Fragment::frames(frames));
210	    };
211	
212	    let pod = Region::new(regions.base(), Axes::splat(false));
213	    let counter = Counter::of(EquationElem::ELEM)
214	        .display_at(engine, elem.location().unwrap(), styles, numbering, span)?
215	        .spanned(span);
216	    let mut locator = locator.split();
217	    let number = crate::layout_frame(engine, &counter, locator.next(&()), styles, pod)?;
218	
219	    static NUMBER_GUTTER: Em = Em::new(0.5);
220	    let full_number_width = number.width() + NUMBER_GUTTER.resolve(styles);
221	
222	    let number_align = match elem.number_align.get(styles) {
223	        SpecificAlignment::H(h) => SpecificAlignment::Both(h, VAlignment::Horizon),
224	        SpecificAlignment::V(v) => SpecificAlignment::Both(OuterHAlignment::End, v),
225	        SpecificAlignment::Both(h, v) => SpecificAlignment::Both(h, v),
226	    };
227	
228	    // Add equation numbers to each equation region.
229	    let region_count = equation_builders.len();
230	    let frames = equation_builders
231	        .into_iter()
232	        .map(|builder| {
233	            if builder.frames.is_empty() && region_count > 1 {
234	                // Don't number empty regions, but do number empty equations.
235	                return builder.build_aligned();
236	            }
237	            add_equation_number(
238	                builder,
239	                number.clone(),
240	                number_align.resolve(styles),
241	                styles.get(AlignElem::alignment).resolve(styles).x,
242	                regions.size.x,
243	                full_number_width,
244	            )
245	        })
246	        .collect();
247	
248	    Ok(Fragment::frames(frames))
249	}
250	
251	fn add_equation_number(
252	    equation_builder: MathRunFrameBuilder,
253	    number: Frame,
254	    number_align: Axes<FixedAlignment>,
255	    equation_align: FixedAlignment,
256	    region_size_x: Abs,
257	    full_number_width: Abs,
258	) -> Frame {
259	    let first =
260	        equation_builder.frames.first().map_or(
261	            (equation_builder.size, Point::zero(), Abs::zero()),
262	            |(frame, pos)| (frame.size(), *pos, frame.baseline()),
263	        );
264	    let last =
265	        equation_builder.frames.last().map_or(
266	            (equation_builder.size, Point::zero(), Abs::zero()),
267	            |(frame, pos)| (frame.size(), *pos, frame.baseline()),
268	        );
269	    let line_count = equation_builder.frames.len();
270	    let mut equation = equation_builder.build_aligned();
271	
272	    let width = if region_size_x.is_finite() {
273	        region_size_x
274	    } else {
275	        equation.width() + 2.0 * full_number_width
276	    };
277	
278	    let is_multiline = line_count >= 2;
279	    let resizing_offset = resize_equation(
280	        &mut equation,
281	        &number,
282	        number_align,
283	        equation_align,
284	        width,
285	        is_multiline,
286	        [first, last],
287	    );
288	    equation.translate(Point::with_x(match (equation_align, number_align.x) {
289	        (FixedAlignment::Start, FixedAlignment::Start) => full_number_width,
290	        (FixedAlignment::End, FixedAlignment::End) => -full_number_width,
291	        _ => Abs::zero(),
292	    }));
293	
294	    let x = match number_align.x {
295	        FixedAlignment::Start => Abs::zero(),
296	        FixedAlignment::End => equation.width() - number.width(),
297	        FixedAlignment::Center => unreachable!(),
298	    };
299	    let y = {
300	        let align_baselines = |(_, pos, baseline): (_, Point, Abs), number: &Frame| {
301	            resizing_offset.y + pos.y + baseline - number.baseline()
302	        };
303	        match number_align.y {
304	            FixedAlignment::Start => align_baselines(first, &number),
305	            FixedAlignment::Center if !is_multiline => align_baselines(first, &number),
306	            // In this case, the center lines (not baselines) of the number frame
307	            // and the equation frame shall be aligned.
308	            FixedAlignment::Center => (equation.height() - number.height()) / 2.0,
309	            FixedAlignment::End => align_baselines(last, &number),
310	        }
311	    };
312	
313	    equation.push_frame(Point::new(x, y), number);
314	    equation
315	}
316	
317	/// Resize the equation's frame accordingly so that it encompasses the number.
318	fn resize_equation(
319	    equation: &mut Frame,
320	    number: &Frame,
321	    number_align: Axes<FixedAlignment>,
322	    equation_align: FixedAlignment,
323	    width: Abs,
324	    is_multiline: bool,
325	    [first, last]: [(Axes<Abs>, Point, Abs); 2],
326	) -> Point {
327	    if matches!(number_align.y, FixedAlignment::Center if is_multiline) {
328	        // In this case, the center lines (not baselines) of the number frame
329	        // and the equation frame shall be aligned.
330	        return equation.resize(
331	            Size::new(width, equation.height().max(number.height())),
332	            Axes::<FixedAlignment>::new(equation_align, FixedAlignment::Center),
333	        );
334	    }
335	
336	    let excess_above = Abs::zero().max({
337	        if !is_multiline || matches!(number_align.y, FixedAlignment::Start) {
338	            let (.., baseline) = first;
339	            number.baseline() - baseline
340	        } else {
341	            Abs::zero()
342	        }
343	    });
344	    let excess_below = Abs::zero().max({
345	        if !is_multiline || matches!(number_align.y, FixedAlignment::End) {
346	            let (size, .., baseline) = last;
347	            (number.height() - number.baseline()) - (size.y - baseline)
348	        } else {
349	            Abs::zero()
350	        }
351	    });
352	
353	    // The vertical expansion is asymmetric on the top and bottom edges, so we
354	    // first align at the top then translate the content downward later.
355	    let resizing_offset = equation.resize(
356	        Size::new(width, equation.height() + excess_above + excess_below),
357	        Axes::<FixedAlignment>::new(equation_align, FixedAlignment::Start),
358	    );
359	    equation.translate(Point::with_y(excess_above));
360	    resizing_offset + Point::with_y(excess_above)
361	}
362	
363	/// The context for math layout.
364	struct MathContext<'v, 'e> {
365	    // External.
366	    engine: &'v mut Engine<'e>,
367	    region: Region,
368	    // Mutable.
369	    fonts_stack: Vec<FontInstance>,
370	    fragments: MathRun,
371	}
372	
373	impl<'v, 'e> MathContext<'v, 'e> {
374	    /// Create a new math context.
375	    fn new(engine: &'v mut Engine<'e>, base: Size, font: FontInstance) -> Self {
376	        Self {
377	            engine,
378	            region: Region::new(base, Axes::splat(false)),
379	            fonts_stack: vec![font],
380	            fragments: vec![],
381	        }
382	    }
383	
384	    /// Get the current base font.
385	    #[inline]
386	    fn font(&self) -> &FontInstance {
387	        // Will always be at least one font in the stack.
388	        self.fonts_stack.last().unwrap()
389	    }
390	
391	    /// Push a fragment.
392	    fn push(&mut self, fragment: impl Into<MathFragment>) {
393	        self.fragments.push(fragment.into());
394	    }
395	
396	    /// Push multiple fragments.
397	    fn extend(&mut self, fragments: impl IntoIterator<Item = MathFragment>) {
398	        self.fragments.extend(fragments);
399	    }
400	
401	    /// Layout the given math item and return the resulting [`MathFragment`]s.
402	    fn layout_into_fragments(
403	        &mut self,
404	        item: &MathItem,
405	        styles: StyleChain,
406	    ) -> SourceResult<MathRun> {
407	        let start = self.fragments.len();
408	        self.layout_into_self(item, styles)?;
409	        Ok(self.fragments.drain(start..).collect())
410	    }
411	
412	    /// Layout the given math item and return the resulting [`MathFragment`]s.
413	    fn layout_into_fragment(
414	        &mut self,
415	        item: &MathItem,
416	        styles: StyleChain,
417	    ) -> SourceResult<MathFragment> {
418	        let fragments = self.layout_into_fragments(item, styles)?;
419	        if fragments.len() == 1 {
420	            return Ok(fragments.into_iter().next().unwrap());
421	        }
422	
423	        // Fragments without a math_size are ignored: the notion of size does
424	        // not apply to them, so their text-likeness is meaningless.
425	        let text_like = fragments
426	            .iter()
427	            .filter(|e| e.math_size().is_some())
428	            .all(|e| e.is_text_like());
429	
430	        let styles = item.styles().unwrap_or(styles);
431	        let props = MathProperties::default(styles, Span::detached());
432	        let frame = fragments.into_frame();
433	        Ok(FrameFragment::new(&props, styles, frame)
434	            .with_text_like(text_like)
435	            .into())
436	    }
437	
438	    fn layout_into_self(
439	        &mut self,
440	        item: &MathItem,
441	        styles: StyleChain,
442	    ) -> SourceResult<()> {
443	        let outer_styles = item.styles().unwrap_or(styles);
444	        let outer_font = outer_styles.get_ref(TextElem::font);
445	
446	        for item in item.as_slice() {
447	            let styles = item.styles().unwrap_or(outer_styles);
448	
449	            // Whilst this check isn't exact, it more or less suffices as a
450	            // change in font variant probably won't have an effect on metrics.
451	            if styles != outer_styles && styles.get_ref(TextElem::font) != outer_font {
452	                self.fonts_stack
453	                    .push(get_font(self.engine.world, styles, item.span())?);
454	                let scale_style = style_for_script_scale(self.font());
455	                layout_realized(item, self, styles.chain(&scale_style))?;
456	                self.fonts_stack.pop();
457	            } else {
458	                layout_realized(item, self, styles)?;
459	            }
460	        }
461	
462	        Ok(())
463	    }
464	}
465	
466	/// Lays out a single math item.
467	fn layout_realized(
468	    item: &MathItem,
469	    ctx: &mut MathContext,
470	    styles: StyleChain,
471	) -> SourceResult<()> {
472	    // Handle non-component items first.
473	    let comp = match item {
474	        MathItem::Component(comp) => comp,
475	        MathItem::Spacing(amount, font_size, _) => {
476	            ctx.push(MathFragment::Space(amount.at(*font_size)));
477	            return Ok(());
478	        }
479	        MathItem::Space => {
480	            ctx.push(MathFragment::Space(ctx.font().math().space_width.resolve(styles)));
481	            return Ok(());
482	        }
483	        MathItem::Tag(tag) => {
484	            ctx.push(MathFragment::Tag(tag.clone()));
485	            return Ok(());
486	        }
487	    };
488	
489	    let props = &comp.props;
490	
491	    // Insert left spacing. Items with an alignment form get their spacing
492	    // handled by the multiline layout instead.
493	    if let Some(lspace) = props.lspace
494	        && !props.align_form_infix
495	        && !lspace.is_zero()
496	    {
497	        let width = lspace.at(styles.resolve(TextElem::size));
498	        ctx.push(MathFragment::Space(width));
499	    }
500	
501	    // Dispatch based on item kind to the appropriate layout function.
502	    match &comp.kind {
503	        MathKind::Box(item) => layout_box(item, ctx, styles, props)?,
504	        MathKind::Mathml(item) => layout_mathml(item, ctx, styles, props)?,
505	        MathKind::External(item) => layout_external(item, ctx, styles, props)?,
506	        MathKind::Glyph(item) => layout_glyph(item, ctx, styles, props)?,
507	        MathKind::Cancel(item) => layout_cancel(item, ctx, styles, props)?,
508	        MathKind::Radical(item) => layout_radical(item, ctx, styles, props)?,
509	        MathKind::Line(item) => layout_line(item, ctx, styles, props)?,
510	        MathKind::Accent(item) => layout_accent(item, ctx, styles, props)?,
511	        MathKind::Scripts(item) => layout_scripts(item, ctx, styles, props)?,
512	        MathKind::Primes(item) => layout_primes(item, ctx, styles, props)?,
513	        MathKind::Table(item) => layout_table(item, ctx, styles, props)?,
514	        MathKind::Fraction(item) => layout_fraction(item, ctx, styles, props)?,
515	        MathKind::SkewedFraction(item) => {
516	            layout_skewed_fraction(item, ctx, styles, props)?;
517	        }
518	        MathKind::Text(item) => layout_text(item, ctx, styles, props)?,
519	        MathKind::Number(item) => layout_number(item, ctx, styles, props)?,
520	        MathKind::Fenced(item) => layout_fenced(item, ctx, styles, props)?,
521	        MathKind::Multiline(item) => {
522	            // Don't set the baseline by default, unless the item is centered.
523	            let mut frame = layout_multiline(item, ctx, styles)?.build_unaligned();
524	            if item.centered {
525	                let axis = ctx.font().math().axis_height.resolve(styles);
526	                frame.set_baseline(frame.height() / 2.0 + axis);
527	            }
528	            ctx.push(FrameFragment::new(props, styles, frame));
529	        }
530	        MathKind::Group(_) => {
531	            let fragment = ctx.layout_into_fragment(item, styles)?;
532	            let italics = fragment.italics_correction();
533	            let accent_attach = fragment.accent_attach();
534	            ctx.push(
535	                FrameFragment::new(props, styles, fragment.into_frame())
536	                    .with_italics_correction(italics)
537	                    .with_accent_attach(accent_attach),
538	            );
539	        }
540	    }
541	
542	    // Insert right spacing.
543	    if let Some(rspace) = props.rspace
544	        && !rspace.is_zero()
545	    {
546	        let width = rspace.at(styles.resolve(TextElem::size));
547	        ctx.push(MathFragment::Space(width));
548	    }
549	
550	    Ok(())
551	}
552	
553	/// Ignore a MathML HTML element during paged export.
554	fn layout_mathml(
555	    item: &MathmlItem,
556	    ctx: &mut MathContext,
557	    _styles: StyleChain,
558	    _props: &MathProperties,
559	) -> SourceResult<()> {
560	    ctx.engine.sink.warn(warning!(
561	        item.elem.span(),
562	        "MathML element was ignored during paged export",
563	    ));
564	    Ok(())
565	}
566	
567	/// Lays out a [`BoxItem`].
568	fn layout_box(
569	    item: &BoxItem,
570	    ctx: &mut MathContext,
571	    styles: StyleChain,
572	    props: &MathProperties,
573	) -> SourceResult<()> {
574	    let frame = crate::inline::layout_box(
575	        item.elem,
576	        ctx.engine,
577	        item.locator.relayout(),
578	        styles,
579	        ctx.region.size,
580	    )?;
581	    ctx.push(FrameFragment::new(props, styles, frame));
582	    Ok(())
583	}
584	
585	/// Layout into a frame with normal layout.
586	fn layout_external(
587	    item: &ExternalItem,
588	    ctx: &mut MathContext,
589	    styles: StyleChain,
590	    props: &MathProperties,
591	) -> SourceResult<()> {
592	    let mut frame = crate::layout_frame(
593	        ctx.engine,
594	        item.content,
595	        item.locator.relayout(),
596	        styles,
597	        ctx.region,
598	    )?;
599	    if !frame.has_baseline() {
600	        let axis = ctx.font().math().axis_height.resolve(styles);
601	        frame.set_baseline(frame.height() / 2.0 + axis);
602	    }
603	    ctx.push(FrameFragment::new(props, styles, frame));
604	    Ok(())
605	}
606	
607	/// Styles to add font constants to the style chain.
608	fn style_for_script_scale(font: &FontInstance) -> LazyHash<Style> {
609	    EquationElem::script_scale
610	        .set((
611	            font.math().script_percent_scale_down,
612	            font.math().script_script_percent_scale_down,
613	        ))
614	        .wrap()
615	}
616	
617	/// Get the current base font.
618	fn get_font(
619	    world: Tracked<dyn World + '_>,
620	    styles: StyleChain,
621	    span: Span,
622	) -> SourceResult<FontInstance> {
623	    let variant = variant(styles);
624	    let size = styles.resolve(TextElem::size);
625	    let variations = styles.get_cloned(TextElem::variations);
626	    families(styles)
627	        .find_map(|family| {
628	            world
629	                .book()
630	                .select(family.as_str(), variant)
631	                .and_then(|id| world.font(id))
632	                .filter(|_| family.covers().is_none())
633	                .map(|font| font.instantiate(variant, size, &variations))
634	        })
635	        .ok_or("no font could be found")
636	        .at(span)
637	}
638	
639	/// Check if the top-level base font has a MATH table.
640	fn warn_non_math_font(font: &Font, engine: &mut Engine, span: Span) {
641	    if !font.info().flags.contains(FontFlags::MATH) {
642	        engine.sink.warn(warning!(
643	            span,
644	            "current font is not designed for math";
645	            hint: "rendering may be poor";
646	        ));
647	    }
648	}
