33	/// Similar to a [`StackChild`], but with an additional variant that allows
34	/// specifying a custom layouter for a child. Useful when using stack layout to
35	/// create other layouters, such as that of lists.
36	pub enum StackLayoutChild<'a, F>
37	where
38	    F: Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
39	{
40	    /// A stack child with content or spacing.
41	    StackChild(&'a StackChild),
42	    /// A child with a custom layouter, producing its own frames.
43	    CustomLayouter(F),
44	}
45	
46	impl<'a, F> From<&'a StackChild> for StackLayoutChild<'a, F>
47	where
48	    F: Fn(&mut Engine, StyleChain, Regions) -> SourceResult<Fragment>,
49	{
50	    fn from(value: &'a StackChild) -> Self {
51	        Self::StackChild(value)
52	    }
